#include <bits/stdc++.h>
using namespace std;

static bool tagChar(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    long long n, now, w;
    stringstream(line) >> n >> now >> w;
    unordered_map<string, int> c;
    for (int k = 0; k < n && getline(cin, line); k++) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        size_t tab = line.find('\t');
        long long t = stoll(line.substr(0, tab));
        if (t < now - w || t > now) continue;  // outside the closed window
        // A tag is '#' followed by at least one ASCII letter, digit or underscore.
        for (size_t i = tab + 1; i < line.size();) {
            if (line[i] != '#') {
                i++;
                continue;
            }
            size_t j = i + 1;
            while (j < line.size() && tagChar(line[j])) j++;
            if (j > i + 1) c[line.substr(i, j - i)]++;
            i = j;
        }
    }
    vector<pair<int, string>> v;
    for (auto &[tag, cnt] : c) v.push_back({-cnt, tag});
    sort(v.begin(), v.end());
    string out;
    for (size_t i = 0; i < min<size_t>(3, v.size()); i++) out += (i ? "\n" : "") + v[i].second;
    cout << out << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static boolean tagChar(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken()), now = Long.parseLong(st.nextToken()), w = Long.parseLong(st.nextToken());
        HashMap<String, Integer> c = new HashMap<>();
        String line;
        for (int k = 0; k < n && (line = br.readLine()) != null; k++) {
            int tab = line.indexOf('\t');
            long t = Long.parseLong(line.substring(0, tab).trim());
            if (t < now - w || t > now) continue;
            for (int i = tab + 1; i < line.length();) {
                if (line.charAt(i) != '#') {
                    i++;
                    continue;
                }
                int j = i + 1;
                while (j < line.length() && tagChar(line.charAt(j))) j++;
                if (j > i + 1) c.merge(line.substring(i, j), 1, Integer::sum);
                i = j;
            }
        }
        List<String> tags = new ArrayList<>(c.keySet());
        tags.sort((a, b) -> !c.get(a).equals(c.get(b)) ? c.get(b) - c.get(a) : a.compareTo(b));
        System.out.println(String.join("\n", tags.subList(0, Math.min(3, tags.size()))));
    }
}

package main

import (
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func tagChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(string(data), "\n")
	head := strings.Fields(lines[0])
	n, _ := strconv.Atoi(head[0])
	now, _ := strconv.Atoi(head[1])
	w, _ := strconv.Atoi(head[2])
	c := map[string]int{}
	for k := 1; k <= n && k < len(lines); k++ {
		line := strings.TrimSuffix(lines[k], "\r")
		tab := strings.IndexByte(line, '\t')
		t, _ := strconv.Atoi(strings.TrimSpace(line[:tab]))
		if t < now-w || t > now {
			continue
		}
		for i := tab + 1; i < len(line); {
			if line[i] != '#' {
				i++
				continue
			}
			j := i + 1
			for j < len(line) && tagChar(line[j]) {
				j++
			}
			if j > i+1 {
				c[line[i:j]]++
			}
			i = j
		}
	}
	tags := make([]string, 0, len(c))
	for tag := range c {
		tags = append(tags, tag)
	}
	sort.Slice(tags, func(i, j int) bool {
		if c[tags[i]] != c[tags[j]] {
			return c[tags[i]] > c[tags[j]]
		}
		return tags[i] < tags[j]
	})
	os.Stdout.WriteString(strings.Join(tags[:min(3, len(tags))], "\n") + "\n")
}
